        Map<String, List<String>> comments = config.comments;
        config.setComment(path, commentLine1, commentLine2);
        assertThat(comments.containsKey(path), is(true));
    }

    @Test
    public void newCommentsConfiguration_setComment_overridesExistingEntry() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "path";
        String existingCommentLine = "existing line";
        Map<String, List<String>> comments = config.comments;
        config.setComment(path, existingCommentLine);
        String commentLine1 = "line1";
        String commentLine2 = "line2";
        config.setComment(path, commentLine1, commentLine2);
        assertThat(comments.get(path).contains(existingCommentLine), is(false));
    }

    @Test
    public void newCommentsConfiguration_setComment_addsNewLine() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "path";
        String commentLines[] = {"line1", "\n"};
        Map<String, List<String>> comments = config.comments;
        config.setComment(path, commentLines);
        assertThat(comments.get(path).get(0), is("line1"));
    }

    @Test
    public void newCommentsConfiguration_getAllComments_isUnmodifiable() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> comments = config.comments;
        Map<String, @UnmodifiableView List<String>> getAllComments = config.getAllComments();
        assertThat(getAllComments(comments), is(isUnmodifiable()));
    }

    @Test
    public void newCommentsConfiguration_getAllComments_returnsEmptyListForEmptyMap() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> comments = Collections.emptyMap();
        Map<String, @UnmodifiableView List<String>> getAllComments = config.getAllComments();
        assertThat(getAllComments(comments), is(isEmptyList()));
    }

    private static boolean isUnmodifiable(Map<String, List<String>> map) {
        return map == null || !map instanceof Map;
    }

    private static boolean isEmptyMap(Map<String, List<String>> map) {
        return map == null && map.isEmpty();
    }

    private static boolean isEmptyList(List<String> list) {
        return list == null && list.isEmpty();
    }

    private static <T> @UnmodifiableView T isUnmodifiable(T obj) {
        return Objects.requireNonNull(obj);
    }
